/* Clients + New job data. ServiceM8 is the master: clients (company), contacts (companycontact) and jobs are read live from it, so changes made in ServiceM8 show in the hub.
   The hub table cbs_client_contacts only adds each contact's role (matched by sm8_uuid) and holds people not yet in ServiceM8.
   Blank contacts that ServiceM8 creates automatically are hidden. The client's primary BILLING contact is its accounts contact: shown in the client details AND in the contacts list
   (ServiceM8 makes a client's first contact its billing contact, so hiding it would make people vanish).
   Every ServiceM8 list is de-duplicated by uuid (safety net: the lookups must run once, see executeOnce on ND Contacts / ND Jobs).
   Output shape kept for New job: clients[{uuid,name,address}], folders, people{client_uuid:[{id,name,role,phone,email}]}; extra fields for the Clients page. */
const S=v=>v==null?'':String(v).trim();
const nm=c=>[S(c.first),S(c.last)].filter(Boolean).join(' ');
const arr=n=>{try{return $(n).all().map(i=>i.json);}catch(e){return [];}};
const uniq=a=>{const s={};return a.filter(x=>{if(!x||!x.uuid||s[x.uuid])return false;s[x.uuid]=1;return true;});};
const CO=uniq(arr('ND Clients')).filter(x=>String(x.active)!=='0'&&S(x.name));
const CC=uniq(arr('ND Contacts')).filter(x=>x.company_uuid&&String(x.active)!=='0');
const JB=uniq(arr('ND Jobs')).filter(x=>String(x.active)!=='0');
const HR=arr('ND People').filter(r=>r&&S(r.client_uuid)&&S(r.name)&&S(r.active)!=='0');
const F=[...new Set(uniq(arr('ND Queues')).filter(x=>S(x.name)&&String(x.active)!=='0').map(x=>S(x.name)))];
const byU={};HR.forEach(r=>{if(S(r.sm8_uuid))byU[S(r.sm8_uuid)]=r;});
const TYPE={BILLING:'Accounts',JOB:'','Property Manager':'Property manager'};
const BILL={};CC.forEach(c=>{if(S(c.type)==='BILLING'&&String(c.is_primary_contact)==='1'&&!BILL[c.company_uuid])BILL[c.company_uuid]=c;});
const P={},seen={};
CC.forEach(c=>{const n=nm(c),ph=S(c.phone)||S(c.mobile),em=S(c.email);if(!n&&!ph&&!em)return;const h=byU[c.uuid];if(h)seen[h.id]=1;
 const b=BILL[c.company_uuid],acc=!!(b&&b.uuid===c.uuid);
 (P[c.company_uuid]=P[c.company_uuid]||[]).push({id:h?h.id:'',uuid:c.uuid,name:n||(h?S(h.name):'')||'(no name)',role:(h&&S(h.role))||(acc?'Accounts':(TYPE[S(c.type)]||'')),phone:ph,email:em,accounts:acc});});
/* hub people not yet in ServiceM8 (no sm8_uuid). A hub person whose ServiceM8 contact was deleted in ServiceM8 is not shown (deleted both ways). */
HR.forEach(r=>{if(seen[r.id]||S(r.sm8_uuid))return;(P[r.client_uuid]=P[r.client_uuid]||[]).push({id:r.id,uuid:'',name:S(r.name),role:S(r.role),phone:S(r.phone),email:S(r.email)});});
Object.keys(P).forEach(k=>P[k].sort((a,b)=>a.name.localeCompare(b.name)));
const ST={'Quote':'Estimate','Work Order':'Approved','Completed':'Completed','Unsuccessful':'Unsuccessful'};
const J={};JB.forEach(j=>{const cu=S(j.company_uuid);if(!cu||!S(j.generated_job_id))return;(J[cu]=J[cu]||[]).push({no:S(j.generated_job_id),status:ST[S(j.status)]||S(j.status),site:S(j.job_address).split('\n').join(', '),desc:S(j.job_description).split('\n')[0].slice(0,140),date:S(j.date).slice(0,10)});});
Object.keys(J).forEach(k=>J[k].sort((a,b)=>(Number(b.no)||0)-(Number(a.no)||0)));
const C=CO.map(x=>{const b=BILL[x.uuid],jj=J[x.uuid]||[];return {uuid:x.uuid,name:S(x.name),address:S(x.address)||S(x.address_street)||S(x.billing_address),billing_address:S(x.billing_address),website:S(x.website),abn_number:S(x.abn_number),payment_terms:S(x.payment_terms),
 bill:b?{uuid:b.uuid,name:nm(b),phone:S(b.phone)||S(b.mobile),email:S(b.email)}:null,jobs:jj.slice(0,40),job_count:jj.length};}).sort((a,b)=>a.name.localeCompare(b.name));
return [{json:{ok:true,clients:C,folders:F,people:P,warn:C.length?'':'ServiceM8 clients did not load'}}];

/* Clients page (hub menu: People and companies > Clients). ServiceM8 is the master for clients and contacts: data from cbs-newjob-data (live from ServiceM8, plus each contact's role kept in cbs_client_contacts); every change via cbs-client-people-act is written to ServiceM8 (company / companycontact), so changes made in either place show in both. Payment terms are shown but set in ServiceM8. */
const CSS="*{box-sizing:border-box}body{margin:0;background:#f2f2f0;color:#161616;font-family:system-ui,-apple-system,\"Segoe UI\",Roboto,Arial,sans-serif;font-size:16px;line-height:1.4}header{background:#3d4043;color:#fff;padding:12px 16px;border-bottom:4px solid #F47920;position:sticky;top:0;z-index:5}header .nav{display:flex;flex-wrap:wrap;gap:6px 14px}header a.hub{color:#ffb37a;font-size:13px;text-decoration:none}header h1{margin:4px 0 0;font-size:20px}header p{margin:3px 0 0;color:#ccc;font-size:13px}.wrap{max-width:860px;margin:0 auto;padding:14px}.tools{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:12px;align-items:center}.btn{background:#F47920;color:#fff;font-weight:600;border-radius:8px;padding:8px 14px;font-size:14px;border:0;font-family:inherit;cursor:pointer}.btn.ghost{background:#fff;color:#1d1d1d;border:1px solid #d9d9d6}.btn.sm{padding:6px 10px;font-size:13px}.btn:disabled{opacity:.5}.btn.red{background:#fff;color:#b3261e;border:1px solid #e9b6b1}.srch{width:100%;font:inherit;padding:10px 12px;border:1px solid #ccc;border-radius:10px;margin-bottom:10px;background:#fff}.cl{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:10px}.cc{display:flex;flex-direction:column;gap:4px;text-align:left;font:inherit;color:#161616;background:#fff;border:1px solid #d9d9d6;border-radius:12px;padding:12px 14px;cursor:pointer}.cc:hover{border-color:#F47920}.cc b{font-size:16px}.cc .ad{color:#555;font-size:13.5px;overflow:hidden;text-overflow:ellipsis;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}.cc .ct{color:#6b6e70;font-size:12.5px}.back{display:inline-block;color:#b85a12;text-decoration:none;font-size:14px;font-weight:600;margin:2px 0 6px}.cn{margin:0 0 12px;font-size:22px}.card{background:#fff;border:1px solid #d9d9d6;border-radius:12px;margin-bottom:12px;overflow:hidden}.ch{display:flex;align-items:center;gap:8px;padding:10px 14px;background:#f8f8f6;border-bottom:1px solid #ecece9;font-weight:700}.ch span{flex:1}.ch small{font-weight:400;color:#6b6e70;margin-left:4px}.cb{padding:4px 14px 10px}.dr{display:grid;grid-template-columns:170px 1fr;gap:10px;padding:8px 0;border-top:1px solid #f0f0ee}.dr:first-child{border-top:0}.dr span{color:#6b6e70;font-size:14px}.dr div{overflow-wrap:anywhere}.dr a,.p .m a{color:#1f5fbf;text-decoration:none}.p{display:flex;gap:10px;align-items:flex-start;padding:10px 14px;border-top:1px solid #f0f0ee}.p:first-of-type{border-top:0}.p .i{flex:1;min-width:0}.p .n{font-weight:600}.p .rl{font-weight:400;color:#6b6e70;font-size:13.5px;margin-left:4px}.p .m{color:#555;font-size:14px;margin-top:2px;overflow-wrap:anywhere}.p .b{display:flex;gap:6px;flex:0 0 auto}.jb{display:flex;align-items:center;gap:10px;padding:10px 14px;border-top:1px solid #f0f0ee;text-decoration:none;color:#161616}.jb:hover{background:#f8f8f6}.jb b{flex:0 0 auto}.jb .jd{flex:1;min-width:0;color:#555;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.st{flex:0 0 auto;font-size:12px;font-weight:600;border-radius:999px;padding:2px 8px;background:#eee;color:#444}.st-approved{background:#e3f1e5;color:#1e6b2e}.st-estimate{background:#fff1dc;color:#8a5a00}.st-completed{background:#e6eefb;color:#1f4f9a}.st-unsuccessful{background:#f6e3e1;color:#8a2a1e}.empty{color:#6b6e70;padding:18px 14px;text-align:center;background:#fff;border:1px dashed #d9d9d6;border-radius:12px}.none{color:#6b6e70;font-size:14px;padding:10px 14px}.ov{position:fixed;inset:0;background:rgba(0,0,0,.45);display:flex;align-items:flex-start;justify-content:center;padding:20px 10px;overflow:auto;z-index:20}.dlg{background:#fff;border-radius:14px;max-width:560px;width:100%;padding:16px}.dlg h2{margin:0 0 10px;font-size:18px}.dlg h3{margin:16px 0 0;font-size:15px;color:#3d4043;border-top:1px solid #eee;padding-top:12px}label.f{display:block;font-size:13px;font-weight:600;color:#444;margin:10px 0 4px}.dlg input:not([type=checkbox]),.dlg textarea{width:100%;font:inherit;padding:10px;border:1px solid #c4c6c8;border-radius:8px;background:#fff}.chkl{font-size:14px;color:#444;display:flex;gap:6px;align-items:center;margin-top:8px}.row2{display:grid;grid-template-columns:1fr 1fr;gap:8px}.msg{font-size:14px;color:#8a5a00;margin-top:8px;min-height:18px}.note{font-size:13px;color:#6b6e70;margin-top:8px}.bb{display:flex;flex-wrap:wrap;gap:6px;margin-top:12px}@media(max-width:560px){.p{flex-wrap:wrap}.p .b{width:100%}.row2{grid-template-columns:1fr}.dr{grid-template-columns:1fr;gap:2px}}";
const nav='<div class="nav"><a class="hub" href="/webhook/cbs-admin">&larr; Operations Hub</a><a class="hub" href="/webhook/cbs-jobs">Jobs</a></div>';
const html='<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Clients</title><script src="/webhook/cbs-guard"></script><style>'+CSS+'</style></head><body><header>'+nav+'<h1>Clients</h1><p>Clients and their contacts. Saved to ServiceM8, and changes made in ServiceM8 show here.</p></header><div class="wrap" id="app"><div class="empty">Loading\u2026</div></div><script>('+client.toString()+')();</script></body></html>';
return [{json:{html:html}}];

function client(){
var app=document.getElementById('app'),DATA=null,Q='',BUSY=false;
function s(v){return v==null?'':String(v);}
function e(t){return s(t).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function nl(t){return e(t).replace(/\n/g,'<br>');}
function who(){var x='';try{var m=JSON.parse(localStorage.getItem('cbs_me')||'null');if(m&&m.name)x=m.name;}catch(z){}if(!x){try{x=localStorage.getItem('cbs_name')||'';}catch(z){}}if(!x){x=(prompt('Your name:')||'').trim();if(x){try{localStorage.setItem('cbs_name',x);}catch(z){}}}return x;}
function post(body){var by=who();if(!by)return Promise.resolve({ok:false,cancel:true});body.by=by;
 return fetch('/webhook/cbs-client-people-act',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}).then(function(r){if(!r.ok)throw 0;return r.json();}).catch(function(){return {ok:false,message:'Could not save. Check your connection and try again.'};});}
function load(){return fetch('/webhook/cbs-newjob-data?_='+Date.now(),{cache:'no-store'}).then(function(r){return r.json();}).then(function(d){DATA=d;render();return d;}).catch(function(){app.innerHTML='<div class="empty">Could not load. Refresh to try again.</div>';});}
function clients(){return (DATA&&DATA.clients)||[];}
function ppl(u){return ((DATA&&DATA.people)||{})[u]||[];}
function cl(u){return clients().filter(function(x){return x.uuid===u;})[0]||null;}
function cur(){var m=location.hash.match(/^#c=([^&]+)/);return m?decodeURIComponent(m[1]):'';}
function go(u){if(u)location.hash='c='+encodeURIComponent(u);else{history.pushState('',document.title,location.pathname+location.search);render();}window.scrollTo(0,0);}
function dlg(html){var o=document.createElement('div');o.className='ov';o.innerHTML='<div class="dlg">'+html+'</div>';document.body.appendChild(o);o.close=function(){o.remove();};return o;}
function guard(o,dirty){o.addEventListener('click',function(ev){if(ev.target!==o)return;if(dirty&&dirty()&&!confirm('Close without saving your changes?'))return;o.close();});
 var x=o.querySelector('#dx');if(x)x.onclick=function(){if(dirty&&dirty()&&!confirm('Close without saving your changes?'))return;o.close();};}
function tel(p){return p?'<a href="tel:'+e(p.replace(/\s+/g,''))+'">'+e(p)+'</a>':'';}
function mail(m){return m?'<a href="mailto:'+e(m)+'">'+e(m)+'</a>':'';}
function render(){if(!DATA)return;var u=cur();if(u&&cl(u))return one(cl(u));list();}
function list(){var q=Q.toLowerCase(),h='';
 h+='<div class="tools"><button class="btn" id="newc">+ New client</button></div>';
 if(DATA.warn)h+='<div class="empty" style="margin-bottom:10px">'+e(DATA.warn)+'</div>';
 h+='<input class="srch" id="q" type="search" placeholder="Search clients, contacts, addresses" value="'+e(Q)+'">';
 var L=clients().filter(function(c){if(!q)return true;var t=[c.name,c.address,c.billing_address,c.bill&&c.bill.name].concat(ppl(c.uuid).map(function(p){return [p.name,p.role,p.phone,p.email].join(' ');})).join(' ').toLowerCase();return t.indexOf(q)>-1;});
 if(!clients().length&&!DATA.warn)h+='<div class="empty">No clients yet. Tap + New client.</div>';
 else if(!L.length)h+='<div class="empty">Nothing matches.</div>';
 h+='<div class="cl">';L.forEach(function(c){var n=ppl(c.uuid).length;h+='<button class="cc" data-u="'+e(c.uuid)+'"><b>'+e(c.name)+'</b><span class="ad">'+(c.address?e(c.address.split('\n').join(', ')):'<i>No address</i>')+'</span><span class="ct">'+n+' '+(n===1?'contact':'contacts')+' \u00b7 '+c.job_count+' '+(c.job_count===1?'job':'jobs')+'</span></button>';});h+='</div>';
 app.innerHTML=h;
 document.getElementById('newc').onclick=function(){clientDlg(null);};
 var qi=document.getElementById('q');qi.oninput=function(){Q=qi.value;var p=qi.selectionStart;list();var x=document.getElementById('q');x.focus();try{x.setSelectionRange(p,p);}catch(z){}};
 app.querySelectorAll('.cc').forEach(function(b){b.onclick=function(){go(b.getAttribute('data-u'));};});}
function row(l,v){return v?'<div class="dr"><span>'+l+'</span><div>'+v+'</div></div>':'';}
function one(c){var P=ppl(c.uuid),b=c.bill||{},h='';
 h+='<a class="back" href="#" id="bk">&larr; All clients</a><h2 class="cn">'+e(c.name)+'</h2>';
 h+='<div class="card"><div class="ch"><span>Details</span><button class="btn ghost sm" id="edc">Edit</button></div><div class="cb">'
  +row('Site address',c.address?nl(c.address):'')+row('Billing address',c.billing_address&&c.billing_address!==c.address?nl(c.billing_address):(c.billing_address?'Same as site':''))
  +row('Accounts contact',[e(b.name),tel(b.phone),mail(b.email)].filter(Boolean).join('<br>'))
  +row('Website',c.website?'<a href="'+e(/^https?:/i.test(c.website)?c.website:'https://'+c.website)+'" target="_blank" rel="noopener">'+e(c.website)+'</a>':'')
  +row('Company / VAT number',e(c.abn_number))+row('Payment terms',c.payment_terms?e(c.payment_terms)+' <small style="color:#6b6e70">(set in ServiceM8)</small>':'');
 if(!c.address&&!c.billing_address&&!b.name&&!b.phone&&!b.email&&!c.website&&!c.abn_number&&!c.payment_terms)h+='<div class="none">No details yet. Tap Edit to add them.</div>';
 h+='</div></div>';
 h+='<div class="card"><div class="ch"><span>Contacts <small>'+P.length+'</small></span><button class="btn sm" id="addp">+ Add contact</button></div>';
 if(!P.length)h+='<div class="none">No contacts yet.</div>';
 P.forEach(function(p,i){h+='<div class="p"><div class="i"><div class="n">'+e(p.name)+(p.role?' <span class="rl">'+e(p.role)+'</span>':'')+'</div><div class="m">'+[tel(p.phone),mail(p.email)].filter(Boolean).join(' \u00b7 ')+'</div></div><div class="b"><button class="btn ghost sm" data-ed="'+i+'">Edit</button><button class="btn red sm" data-rm="'+i+'">Remove</button></div></div>';});
 h+='</div>';
 var J=c.jobs||[];h+='<div class="card"><div class="ch"><span>Jobs <small>'+c.job_count+'</small></span></div>';
 if(!J.length)h+='<div class="none">No jobs for this client yet.</div>';
 J.forEach(function(j){h+='<a class="jb" href="/webhook/cbs-job-file?job='+encodeURIComponent(j.no)+'"><b>Job '+e(j.no)+'</b><span class="st st-'+e(j.status.toLowerCase())+'">'+e(j.status)+'</span><span class="jd">'+e(j.desc||j.site)+'</span></a>';});
 if(c.job_count>J.length)h+='<div class="none">Showing the latest '+J.length+'.</div>';
 h+='</div>';
 app.innerHTML=h;
 document.getElementById('bk').onclick=function(ev){ev.preventDefault();go('');};
 document.getElementById('edc').onclick=function(){clientDlg(c);};
 document.getElementById('addp').onclick=function(){personDlg(c,null);};
 app.querySelectorAll('[data-ed]').forEach(function(x){x.onclick=function(){personDlg(c,P[+x.getAttribute('data-ed')]);};});
 app.querySelectorAll('[data-rm]').forEach(function(x){x.onclick=function(){rmP(c,P[+x.getAttribute('data-rm')]);};});}
function clientDlg(c){var isNew=!c;c=c||{};var b=c.bill||{};var same=!c.billing_address||c.billing_address===c.address;
 var o=dlg('<h2>'+(isNew?'New client':'Edit '+e(c.name))+'</h2>'
  +'<label class="f">Client name</label><input id="cn" value="'+e(c.name)+'">'
  +'<label class="f">Site address</label><textarea id="ca" rows="3">'+e(c.address)+'</textarea>'
  +'<label class="chkl"><input type="checkbox" id="cs"'+(same?' checked':'')+'> Billing address is the same</label>'
  +'<div id="cbw"'+(same?' hidden':'')+'><label class="f">Billing address</label><textarea id="cba" rows="3">'+e(same?'':c.billing_address)+'</textarea></div>'
  +'<h3>Accounts contact</h3><label class="f">Name</label><input id="bn" value="'+e(b.name)+'">'
  +'<div class="row2"><div><label class="f">Phone</label><input id="bp" type="tel" value="'+e(b.phone)+'"></div><div><label class="f">Email</label><input id="be" type="email" value="'+e(b.email)+'"></div></div>'
  +'<h3>More</h3><label class="f">Website</label><input id="cw" value="'+e(c.website)+'">'
  +'<label class="f">Company / VAT number</label><input id="cv" value="'+e(c.abn_number)+'">'+(c.payment_terms?'<div class="note">Payment terms: '+e(c.payment_terms)+' (change these in ServiceM8)</div>':'')
  +'<div class="note">Saved to ServiceM8.</div><div class="msg" id="cm"></div><div class="bb"><button class="btn" id="csv">Save</button><button class="btn ghost" id="dx">Cancel</button></div>');
 var cs=o.querySelector('#cs');cs.onchange=function(){o.querySelector('#cbw').hidden=cs.checked;};
 function v(){var a=o.querySelector('#ca').value.trim();return {name:o.querySelector('#cn').value.trim(),address:a,billing_address:cs.checked?a:o.querySelector('#cba').value.trim(),website:o.querySelector('#cw').value.trim(),abn_number:o.querySelector('#cv').value.trim(),
  bill:{uuid:b.uuid||'',name:o.querySelector('#bn').value.trim(),phone:o.querySelector('#bp').value.trim(),email:o.querySelector('#be').value.trim()}};}
 var st=JSON.stringify(v());function dirty(){return JSON.stringify(v())!==st;}guard(o,dirty);setTimeout(function(){o.querySelector('#cn').focus();},50);
 o.querySelector('#csv').onclick=function(){var x=v(),m=o.querySelector('#cm');if(!x.name){m.textContent='Enter the client name.';return;}
  if(x.bill.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(x.bill.email)){m.textContent='Check the accounts email address.';return;}
  if(isNew){var dup=clients().filter(function(k){return k.name.toLowerCase()===x.name.toLowerCase();})[0];if(dup){m.textContent='A client called '+dup.name+' already exists.';return;}}
  else if(!dirty()){o.close();return;}
  var btn=this;btn.disabled=true;m.textContent='Saving\u2026';
  var hasBill=!!(x.bill.name||x.bill.phone||x.bill.email);
  if(!isNew){x.a='client_save';x.uuid=c.uuid;if(!hasBill&&!b.uuid)delete x.bill;
   post(x).then(function(r){if(r&&r.ok){o.close();load();}else{btn.disabled=false;m.textContent=r.cancel?'':((r&&r.message)||'Could not save.');}});return;}
  var bill=x.bill;delete x.bill;x.a='client_new';
  post(x).then(function(r){if(!(r&&r.ok&&r.uuid)){btn.disabled=false;m.textContent=r.cancel?'':((r&&r.message)||'Could not save.');return;}
   var nu=r.uuid;return load().then(function(){var k=cl(nu);if(hasBill&&k){var y={a:'client_save',uuid:nu,name:k.name,address:k.address,billing_address:k.billing_address,website:k.website,abn_number:k.abn_number,bill:{uuid:(k.bill&&k.bill.uuid)||'',name:bill.name,phone:bill.phone,email:bill.email}};
    return post(y).then(function(){return load();});}}).then(function(){o.close();go(nu);});});};}
function personDlg(c,p){var isNew=!p;p=p||{};
 var o=dlg('<h2>'+(isNew?'Add contact':'Edit '+e(p.name))+'</h2><div class="note" style="margin-top:0">'+e(c.name)+'</div>'
  +'<label class="f">Name</label><input id="pn" value="'+e(p.name)+'" placeholder="Full name">'
  +'<label class="f">Role</label><input id="pr" value="'+e(p.role)+'" placeholder="e.g. Facilities manager">'
  +'<div class="row2"><div><label class="f">Phone</label><input id="pp" type="tel" value="'+e(p.phone)+'"></div><div><label class="f">Email</label><input id="pe" type="email" value="'+e(p.email)+'"></div></div>'
  +'<div class="note">Saved to ServiceM8 as a contact for this client. Shows in New job.</div><div class="msg" id="pm"></div><div class="bb"><button class="btn" id="psv">Save</button><button class="btn ghost" id="dx">Cancel</button></div>');
