 if(!ok){err=err||('ServiceM8 did not accept the change'+(r&&r.statusCode?' ('+r.statusCode+')':'')+'. Nothing was changed in the hub.');return;}
 const h=r.headers||{},u=S(h['x-record-uuid']||h['X-Record-UUID']);if(u&&!created)created=u;
